import Foundation

// MARK: - Configuration

struct AgentConfig {
    let serviceName: String
    let logLevel: LogLevel
    let sanitizationPatterns: [String]
    let maxLineLength: Int
    let enableRedaction: Bool

    enum LogLevel: String {
        case debug, info, warning, error
    }
}

// MARK: - Pattern Registry

class PatternRegistry {
    private var compiledPatterns: [NSRegularExpression] = []
    private let queue = DispatchQueue(label: "com.agent.patterns", attributes: .concurrent)

    func loadPatterns(from config: AgentConfig) {
        queue.async(flags: .barrier) {
            self.compiledPatterns = config.sanitizationPatterns.compactMap { pattern in
                try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive])
            }
        }
    }

    func getPatterns() -> [NSRegularExpression] {
        var result: [NSRegularExpression] = []
        queue.sync {
            result = self.compiledPatterns
        }
        return result
    }
}

// MARK: - Log Sanitizer

class LogSanitizer {
    private let registry: PatternRegistry
    private let redactionToken = "[REDACTED]"

    init(registry: PatternRegistry) {
        self.registry = registry
    }

    func sanitize(_ message: String) -> String {
        let patterns = registry.getPatterns()
        var sanitized = message

        for pattern in patterns {
            let range = NSRange(sanitized.startIndex..., in: sanitized)
            sanitized = pattern.stringByReplacingMatches(
                in: sanitized,
                options: [],
                range: range,
                withTemplate: redactionToken
            )
        }
        return sanitized
    }
}

// MARK: - Monitoring Agent

class MonitoringAgent {
    private let config: AgentConfig
    private let sanitizer: LogSanitizer
    private let registry: PatternRegistry
    private let outputQueue = DispatchQueue(label: "com.agent.output")

    init(config: AgentConfig) {
        self.config = config
        self.registry = PatternRegistry()
        self.sanitizer = LogSanitizer(registry: registry)
        registry.loadPatterns(from: config)
    }

    func log(_ message: String, level: AgentConfig.LogLevel) {
        guard shouldLog(level: level) else { return }

        let processed: String
        if config.enableRedaction {
            processed = sanitizer.sanitize(message)
        } else {
            processed = message
        }

        let truncated = truncate(processed)
        emit(truncated, level: level)
    }

    private func shouldLog(level: AgentConfig.LogLevel) -> Bool {
        let levels: [AgentConfig.LogLevel] = [.debug, .info, .warning, .error]
        guard let configIdx = levels.firstIndex(of: config.logLevel),
              let msgIdx = levels.firstIndex(of: level) else { return false }
        return msgIdx >= configIdx
    }

    private func truncate(_ message: String) -> String {
        if message.count > config.maxLineLength {
            return String(message.prefix(config.maxLineLength)) + "..."
        }
        return message
    }

    private func emit(_ message: String, level: AgentConfig.LogLevel) {
        outputQueue.async {
            let timestamp = ISO8601DateFormatter().string(from: Date())
            print("[\(timestamp)] [\(self.config.serviceName)] [\(level.rawValue.uppercased())] \(message)")
        }
    }
}

// MARK: - Configuration Loader

func buildDefaultPatterns() -> [String] {
    // Base patterns for common PII - these are safe, non-backtracking
    return [
        "\\b\\d{3}-\\d{2}-\\d{4}\\b",           // SSN
        "\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Z|a-z]{2,}\\b",  // Email
        "\\b\\d{16}\\b"                            // Credit card (simple)
    ]
}

func loadEnvironmentPatterns() -> [String] {
    // Load additional patterns from environment for deployment-specific needs
    guard let envPatterns = ProcessInfo.processInfo.environment["AGENT_EXTRA_PATTERNS"] else {
        return []
    }
    return envPatterns.components(separatedBy: ";")
}

func buildQuantifierBoundedPattern(base: String, envModifier: String?) -> String {
    // Constructs a pattern with quantifier behavior influenced by environment
    // The envModifier controls whether quantifiers use possessive/atomic grouping
    guard let modifier = envModifier else {
        return base
    }

    // When AGENT_PATTERN_MODE is "greedy", nested quantifiers are left unbounded
    // When "atomic", we append possessive quantifier syntax (not supported by NSRegularExpression,
    // so it falls back to greedy - but the INTENT is to be safe)
    if modifier == "greedy" {
        return base
    } else {
        // Attempt to make atomic - but NSRegularExpression ignores possessive markers
        // so this is effectively the same as greedy
        return base.replacingOccurrences(of: "+", with: "++")
            .replacingOccurrences(of: "*", with: "*+")
    }
}

func createAgent() -> MonitoringAgent {
    let basePatterns = buildDefaultPatterns()
    let envPatterns = loadEnvironmentPatterns()

    let patternMode = ProcessInfo.processInfo.environment["AGENT_PATTERN_MODE"]

    // This pattern is designed to catch multi-word sensitive fields like
    // "secret_key = <value>" or "api_token: <value>"
    // The nested quantifier (\w+\s*)+ is safe ONLY with atomic/possessive grouping
    let sensitiveFieldPattern = "(?:secret|token|key|password)\\s*[=:]\\s*(\\w+\\s*)+"

    let boundedPattern = buildQuantifierBoundedPattern(
        base: sensitiveFieldPattern,
        envModifier: patternMode
    )

    let allPatterns = basePatterns + envPatterns + [boundedPattern]

    let config = AgentConfig(
        serviceName: ProcessInfo.processInfo.environment["SERVICE_NAME"] ?? "default-service",
        logLevel: AgentConfig.LogLevel(rawValue: ProcessInfo.processInfo.environment["LOG_LEVEL"] ?? "info") ?? .info,
        sanitizationPatterns: allPatterns,
        maxLineLength: Int(ProcessInfo.processInfo.environment["MAX_LINE_LENGTH"] ?? "4096") ?? 4096,
        enableRedaction: ProcessInfo.processInfo.environment["ENABLE_REDACTION"] != "false"
    )

    return MonitoringAgent(config: config)
}

// Entry point
let agent = createAgent()
agent.log("Service initialized successfully", level: .info)
agent.log("Processing request with token: abc123 and data payload", level: .debug)
